export function formatBytes(n) {
  if (n < 0) {
    throw new RangeError('Bytes must be non-negative');
  }

  const units = ['B', 'KB', 'MB', 'GB'];
  let unit = 0;
  while (n >= 1024 && unit < units.length - 1) {
    n /= 1024;
    unit += 1;
  }

  return `${n.toFixed(unit === 0 ? 0 : 1)} ${units[unit]}`;
}
